#!/bin/bash
cd /workspace
while IFS= read -r tpl; do
  [ -z "$tpl" ] && continue
  out=$(./executable -i "$tpl" 2>/tmp/mathspec_err.txt)
  rc=$?
  if [ $rc -ne 0 ]; then
    e=$(sed -n 's/.*"err":"\(.*\)"}$/\1/p' /tmp/mathspec_err.txt)
    printf '%s\n  ERR(%d): %s\n' "$tpl" "$rc" "$e"
  else
    printf '%s\n  => [%s]\n' "$tpl" "$out"
  fi
done
SH
